CREATE FUNCTION public.audit_supplier_identity_equivalence() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
        declare
          audit_action text;
        begin
          audit_action := case
            when tg_op = 'INSERT' then 'created'
            when not old.is_active and new.is_active then 'activated'
            when old.is_active and not new.is_active then 'deactivated'
            else 'updated'
          end;
            equivalence_id,
            action,
            canonical_supplier_id,
            equivalent_supplier_id,
            is_active,
            reason,
            actor_id,
            occurred_at
          ) values (
            new.id,
            audit_action,
            new.canonical_supplier_id,
            new.equivalent_supplier_id,
            new.is_active,
            new.reason,
            new.updated_by,
            now()
          );
          return new;
        end
        $$;


