    CONSTRAINT ck_product_supplier_assessments_reliability CHECK (((delivery_reliability_score IS NULL) OR ((delivery_reliability_score >= (0)::numeric) AND (delivery_reliability_score <= (100)::numeric)))),
    CONSTRAINT ck_product_supplier_assessments_status CHECK (((status)::text = ANY ((ARRAY['approved'::character varying, 'discouraged'::character varying, 'blocked'::character varying])::text[]))),
    CONSTRAINT ck_product_supplier_assessments_validity CHECK (((valid_to IS NULL) OR (valid_to >= valid_from)))
);


