-- Name: purchase_order_reconciliations; Type: TABLE; Schema: public; Owner: sentinel
--

CREATE TABLE public.purchase_order_reconciliations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    liquidstock_supplier_order_id uuid NOT NULL,
    liquidstock_order_id uuid NOT NULL,
    supplier_id integer,
    fattura_id integer,
    venue_id uuid NOT NULL,
    status character varying(30) DEFAULT 'awaiting_invoice'::character varying NOT NULL,
    matching_confidence numeric(6,5) DEFAULT '0'::numeric NOT NULL,
    reconciliation_version integer DEFAULT 1 NOT NULL,
    price_tolerance_absolute numeric(12,4) DEFAULT 0.01 NOT NULL,
    price_tolerance_percent numeric(8,4) DEFAULT 1.0 NOT NULL,
    started_at timestamp with time zone,
    completed_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    invoice_supplier_id integer,
    supplier_equivalence_id bigint,
    supplier_equivalence_approved_by integer,
    supplier_equivalence_approved_at timestamp with time zone,
    supplier_equivalence_used_at timestamp with time zone,
    supplier_equivalence_reason_snapshot text,
    CONSTRAINT ck_po_reconciliations_confidence CHECK (((matching_confidence >= (0)::numeric) AND (matching_confidence <= (1)::numeric))),
    CONSTRAINT ck_po_reconciliations_status CHECK (((status)::text = ANY ((ARRAY['pending'::character varying, 'awaiting_invoice'::character varying, 'matching'::character varying, 'partially_matched'::character varying, 'matched'::character varying, 'anomalies_found'::character varying, 'reviewed'::character varying, 'closed'::character varying])::text[]))),
    CONSTRAINT ck_po_reconciliations_supplier_identity_audit CHECK ((((fattura_id IS NULL) AND (invoice_supplier_id IS NULL) AND (supplier_equivalence_id IS NULL) AND (supplier_equivalence_approved_by IS NULL) AND (supplier_equivalence_approved_at IS NULL) AND (supplier_equivalence_used_at IS NULL) AND (supplier_equivalence_reason_snapshot IS NULL)) OR ((fattura_id IS NOT NULL) AND (invoice_supplier_id IS NOT NULL) AND (((supplier_id = invoice_supplier_id) AND (supplier_equivalence_id IS NULL) AND (supplier_equivalence_approved_by IS NULL) AND (supplier_equivalence_approved_at IS NULL) AND (supplier_equivalence_used_at IS NULL) AND (supplier_equivalence_reason_snapshot IS NULL)) OR ((supplier_id <> invoice_supplier_id) AND (supplier_equivalence_id IS NOT NULL) AND (supplier_equivalence_approved_by IS NOT NULL) AND (supplier_equivalence_approved_at IS NOT NULL) AND (supplier_equivalence_used_at IS NOT NULL) AND (supplier_equivalence_reason_snapshot IS NOT NULL)))))),
    CONSTRAINT ck_po_reconciliations_tolerances CHECK (((price_tolerance_absolute >= (0)::numeric) AND (price_tolerance_percent >= (0)::numeric)))
);


