--
-- Name: upload_batches; Type: TABLE; Schema: public; Owner: sentinel
--

CREATE TABLE public.upload_batches (
    id character varying(36) NOT NULL,
    location_id integer,
    user_id integer NOT NULL,
    stato public.stato_batch NOT NULL,
    file_totali integer NOT NULL,
    file_elaborati integer NOT NULL,
    gia_presenti integer NOT NULL,
    errori_formato integer NOT NULL,
    anomalie_generate integer NOT NULL,
    note text,
    created_at timestamp with time zone NOT NULL,
    completed_at timestamp with time zone
);


ALTER TABLE public.upload_batches OWNER TO sentinel;

--
-- Name: utenti; Type: TABLE; Schema: public; Owner: sentinel
--

CREATE TABLE public.utenti (
    id integer NOT NULL,
    email character varying(255) NOT NULL,
    password_hash character varying(255) NOT NULL,
    ruolo public.ruolo_utente NOT NULL,
    location_id integer,
    telegram_chat_id character varying(50),
    refresh_token_version integer DEFAULT 1 NOT NULL,
    attivo boolean NOT NULL
);


ALTER TABLE public.utenti OWNER TO sentinel;

--
-- Name: COLUMN utenti.location_id; Type: COMMENT; Schema: public; Owner: sentinel
--

COMMENT ON COLUMN public.utenti.location_id IS 'NULL per Admin (vede tutto)';


--
-- Name: COLUMN utenti.telegram_chat_id; Type: COMMENT; Schema: public; Owner: sentinel
--

COMMENT ON COLUMN public.utenti.telegram_chat_id IS 'Chat ID per le notifiche Telegram dello Sprint 3';


--
-- Name: COLUMN utenti.refresh_token_version; Type: COMMENT; Schema: public; Owner: sentinel
--

COMMENT ON COLUMN public.utenti.refresh_token_version IS 'Versione per la rotazione del refresh token';


